mapper.insert:
INSERT INTO posts (
    member_id, title, content, category, is_public, is_temp, thumbnail, created_at, updated_at
)
VALUES (
    #{memberId}, #{title}, #{content}, #{category}, #{isPublic}, #{isTemp}, #{thumbnail}, SYSDATE, SYSDATE
)

INSERT INTO post_tags (
    post_id, tag_id
) VALUES (
    #{postId}, #{tagId}
)

mapper.select:
SELECT FROM posts WHERE is_deleted = 'N' AND is_temp = 'N'
AND category = #{category}
ORDER BY created_at DESC OFFSET #{offset} ROWS FETCH NEXT #{limit} ROWS ONLY

SELECT COUNT(*)
FROM post_likes
WHERE post_id = #{postId} AND member_id = #{memberId}

SELECT COUNT(*)
FROM bookmarks
WHERE post_id = #{postId} AND member_id = #{memberId}
